import { test } from 'node:test'
import { posix } from 'node:path'

import { Vfs, buildVfsBundle, loadNodeModules } from '../stasis/src/vfs-bundle.js'
import { json, lockfile } from './vfs-bundle-github.helper.js'

// Without a packageManager, @exodus/stasis/vfs-bundle takes the one whose lockfile installs cwd:
// each supported one's, where that package manager would install cwd from, and only where exactly
// one does. Every lockfile here locks nothing, so nothing is fetched.

const YARN_LOCK = '# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.\n# yarn lockfile v1\n\n\n'
const SOLDEER = { 'foundry.toml': '[profile.default]\nlibs = ["dependencies"]\n\n[dependencies]\n', 'soldeer.lock': 'dependencies = []\n' }

const vfsOf = (files) => {
  const vfs = new Vfs()
  for (const [path, text] of Object.entries(files)) {
    vfs.mkdir(posix.dirname(`/${path}`), { recursive: true })
    if (typeof text === 'string') vfs.writeFile(`/${path}`, text)
    else vfs.symlink(text.symlink, `/${path}`)
  }
  return vfs
}
const pkg = { 'package.json': json({ name: 'p', version: '1.0.0' }), 'a.js': '' }

test('buildVfsBundle takes the one package manager whose lockfile installs cwd', async (t) => {
  const cases = [
    ['pnpm', { ...pkg, 'pnpm-lock.yaml': lockfile('.') }, ['a.js']],
    ['yarn1', { ...pkg, 'yarn.lock': YARN_LOCK }, ['a.js']],
    ['soldeer', { ...SOLDEER, 'src/A.sol': 'pragma solidity ^0.8.0;\n' }, ['src/A.sol']],
    // Another's lockfile out of where that one installs cwd from installs nothing.
    ['pnpm', { ...pkg, 'pnpm-lock.yaml': lockfile('.'), 'other/yarn.lock': YARN_LOCK }, ['a.js']],
  ]
  await Promise.all(cases.map(async ([expected, files, entries]) => {
    const built = await buildVfsBundle({ vfs: vfsOf(files), entries })
    t.assert.equal(built.packageManager, expected, Object.keys(files).join(' '))
    t.assert.deepEqual([...built.bundle.sources.keys()], entries)
  }))
  // One given is taken whatever the lockfiles.
  const both = vfsOf({ ...pkg, 'pnpm-lock.yaml': lockfile('.'), 'yarn.lock': YARN_LOCK })
  t.assert.equal((await buildVfsBundle({ vfs: both, packageManager: 'yarn1', entries: ['a.js'] })).packageManager, 'yarn1')
})

test('buildVfsBundle refuses to choose where no lockfile, or more than one, installs cwd', async (t) => {
  const build = (files, options) => buildVfsBundle({ vfs: vfsOf(files), entries: ['a.js'], ...options })
  await t.assert.rejects(build(pkg), /^Error: buildVfsBundle: no packageManager given, and none of pnpm-lock\.yaml, yarn\.lock, soldeer\.lock installs \/$/u)
  await t.assert.rejects(build({ ...pkg, 'pnpm-lock.yaml': lockfile('.'), 'yarn.lock': YARN_LOCK }), /^Error: buildVfsBundle: no packageManager given, and more than one lockfile installs \/: \/pnpm-lock\.yaml \(pnpm\), \/yarn\.lock \(yarn1\)$/u)
  // Each where its package manager installs cwd from: pnpm the nearest, yarn the one above.
  const nested = { 'yarn.lock': YARN_LOCK, 'package.json': json({ name: 'root', version: '1.0.0' }), 'apps/p/package.json': json({ name: 'p', version: '1.0.0' }), 'apps/p/pnpm-lock.yaml': lockfile('.'), 'apps/p/a.js': '' }
  await t.assert.rejects(build(nested, { cwd: '/apps/p' }), /^Error: buildVfsBundle: no packageManager given, and more than one lockfile installs \/apps\/p: \/apps\/p\/pnpm-lock\.yaml \(pnpm\), \/yarn\.lock \(yarn1\)$/u)
  // pnpm installs a workspace's package from the workspace's root, which holds no lockfile here.
  const workspace = { 'pnpm-workspace.yaml': 'packages:\n  - apps/*\n', 'apps/p/package.json': json({ name: 'p', version: '1.0.0' }), 'apps/p/pnpm-lock.yaml': lockfile('.'), 'apps/p/a.js': '' }
  await t.assert.rejects(build(workspace, { cwd: '/apps/p' }), /^Error: buildVfsBundle: no packageManager given, and none of pnpm-lock\.yaml, yarn\.lock, soldeer\.lock installs \/apps\/p$/u)
  // A JS project beside a Solidity one, which a JS and a Solidity bundle are built from alike.
  await t.assert.rejects(build({ ...pkg, 'pnpm-lock.yaml': lockfile('.'), ...SOLDEER }), /more than one lockfile installs \/: \/pnpm-lock\.yaml \(pnpm\), \/soldeer\.lock \(soldeer\)$/u)
  // What the one detected builds is checked as for one given.
  await t.assert.rejects(build({ ...SOLDEER }), /^Error: buildVfsBundle: only Solidity bundles are built with soldeer$/u)
  await t.assert.rejects(buildVfsBundle({ vfs: new Map(), entries: ['a.js'] }), /^TypeError: buildVfsBundle: vfs must be a @preventive\/vfs Vfs holding the project/u)
})

test('loadNodeModules takes the one of pnpm and yarn 1 whose lockfile installs cwd', async (t) => {
  t.assert.equal((await loadNodeModules({ vfs: vfsOf({ ...pkg, 'pnpm-lock.yaml': lockfile('.') }) })).packageManager, 'pnpm')
  t.assert.equal((await loadNodeModules({ vfs: vfsOf({ ...pkg, 'yarn.lock': YARN_LOCK }) })).packageManager, 'yarn1')
  // soldeer.lock is none of theirs.
  t.assert.equal((await loadNodeModules({ vfs: vfsOf({ ...pkg, 'pnpm-lock.yaml': lockfile('.'), ...SOLDEER }) })).packageManager, 'pnpm')
  await t.assert.rejects(loadNodeModules({ vfs: vfsOf({ ...pkg, ...SOLDEER }) }), /^Error: loadNodeModules: no packageManager given, and none of pnpm-lock\.yaml, yarn\.lock installs \/$/u)
  await t.assert.rejects(loadNodeModules({ vfs: vfsOf({ ...pkg, 'pnpm-lock.yaml': lockfile('.'), 'yarn.lock': YARN_LOCK }) }), /^Error: loadNodeModules: no packageManager given, and more than one lockfile installs \/: /u)
  // Through a link, where it leads, as for one given.
  const linked = vfsOf({ 'apps/package.json': json({ name: 'apps', version: '1.0.0' }), 'apps/yarn.lock': YARN_LOCK, 'apps/p/a.js': '', 'pkg': { symlink: 'apps/p' } })
  const tree = await loadNodeModules({ vfs: linked, cwd: '/pkg' })
  t.assert.deepEqual([tree.packageManager, tree.root], ['yarn1', '/apps'])
  t.assert.equal((await loadNodeModules({ vfs: linked, cwd: '/pkg', packageManager: 'yarn1' })).root, '/apps')
})

test('a packageManagerVersion is only of a package manager given', async (t) => {
  const vfs = vfsOf({ ...pkg, 'pnpm-lock.yaml': lockfile('.') })
  await t.assert.rejects(buildVfsBundle({ vfs, packageManagerVersion: '10.33.4', entries: ['a.js'] }), /^TypeError: buildVfsBundle: packageManagerVersion is only valid with packageManager$/u)
  await t.assert.rejects(loadNodeModules({ vfs, packageManagerVersion: '10.33.4' }), /^TypeError: loadNodeModules: packageManagerVersion is only valid with packageManager$/u)
  t.assert.equal((await loadNodeModules({ vfs, packageManager: 'pnpm', packageManagerVersion: '10.33.4' })).packageManagerVersion, '10.33.4')
})
